<script lang="ts">
  import { t, locale } from '../i18n';
  import { Button, Help, IconButton, PanelSection, TextField } from './kit';
  export interface Variable { name: string; expression: string; error?: string; title?: string }
  let { variables }: { variables: Variable[] } = $props();
  let exprHint = $derived(t('vars.exprHint', 'Any Geometry field takes an expression over these and over objects named in Layers: {examples}.', {}, $locale).split('{examples}'));
</script>
<PanelSection id="varSec" title={t("ui.variables", "Variables", {}, $locale)}>{#each variables as variable}<div class="row var"><TextField class="vname" data-vname={variable.name} value={variable.name} autocomplete="off" aria-label={t("ui.variable.name", "Variable name", {}, $locale)} /><div class="ctl"><TextField data-vexpr={variable.name} value={variable.expression} class={'geomin' + (variable.error ? ' bad' : '')} autocomplete="off" aria-label={t('vars.valueOf', 'Value of {name}', { name: variable.name }, $locale)} title={variable.title} /></div><IconButton icon="close" size="sm" danger class="vdel" data-vdel={variable.name} title={t("ui.delete.variable", "Delete Variable", {}, $locale)} aria-label={t('vars.deleteOf', 'Delete variable {name}', { name: variable.name }, $locale)} /></div>{/each}<div class="btns"><Button data-act="var:add">{t("ui.add.variable", "Add Variable", {}, $locale)}</Button></div><Help kind="hint">{exprHint[0]}<code>w/2</code>, <code>a.east.x + gap</code>, <code>a.r * 2</code>, <code>dist(a, b)</code>{exprHint[1]} {t("vars.exportValues", "The export writes the values.", {}, $locale)}</Help></PanelSection>
